with
sat_portfolio_company_detail_source as (
    select distinct
        company_business_key,
        company_name,
        company_sector,
        company_sub_sector,
        company_country,
        company_lei,
        company_external_id,
        company_reported_on
    from {{ ref("investment__portfolio_company_vault__base") }}
    where company_business_key is not null
),
sat_portfolio_company_detail_fingerprinted as (
    select
        {{ dpf_vault_hash(["company_business_key"]) }} as portfolio_company_hk,
        {{ dpf_vault_hash(["company_name", "company_sector", "company_country", "company_lei", "company_external_id"]) }} as hashdiff,
        1 as hashdiff_basis_version,
        company_name,
        company_sector,
        company_sub_sector,
        company_country,
        company_lei,
        company_external_id,
        company_reported_on as effective_from,
        {{ dpf_publish_timestamp() }} as load_datetime,
        'investment.portfolio_company_vault' as record_source
    from sat_portfolio_company_detail_source
),
sat_portfolio_company_detail_unstored as (
    select
        portfolio_company_hk,
        hashdiff,
        hashdiff_basis_version,
        company_name,
        company_sector,
        company_sub_sector,
        company_country,
        company_lei,
        company_external_id,
        effective_from,
        load_datetime,
        record_source
    from sat_portfolio_company_detail_fingerprinted
    where {{ dpf_vault_new_versions("sat_portfolio_company_detail_fingerprinted", "portfolio_company_hk", "hashdiff", "effective_from", "hashdiff_basis_version", "current") }}
)

select
    cast(portfolio_company_hk as {{ dpf_type('string') }}) as portfolio_company_hk,
    cast(hashdiff as {{ dpf_type('string') }}) as hashdiff,
    cast(hashdiff_basis_version as {{ dpf_type('int') }}) as hashdiff_basis_version,
    cast(company_name as {{ dpf_type('string') }}) as company_name,
    cast(company_sector as {{ dpf_type('string') }}) as company_sector,
    cast(company_sub_sector as {{ dpf_type('string') }}) as company_sub_sector,
    cast(company_country as {{ dpf_type('string') }}) as company_country,
    cast(company_lei as {{ dpf_type('string') }}) as company_lei,
    cast(company_external_id as {{ dpf_type('string') }}) as company_external_id,
    cast(effective_from as {{ dpf_type('date') }}) as effective_from,
    cast(load_datetime as {{ dpf_type('timestamp') }}) as load_datetime,
